use super::*;
use crate::{forging_ring::Config as Ring,inventory::Item,variables::{Varp,Transmit}};
const COUNTER:Varp=Varp{id:62400,permanent:true,transmit:Transmit::Never,bit_protect:true,client_code:-1};
struct Draw(usize);impl RandomSource for Draw{fn below(&mut self,n:u32)->u32{assert_eq!(n,2);self.0+=1;0}}
fn prepared(used:i32,worn:bool)->(World,ActorId,Arc<Request>){let mut w=World::default();w.collision.allocate(3200,3200,0);w.smithing=Some(Config{queue:900,skill:13,max_level:99,xp_rate:1.0,tutorial:None});w.forging_ring=Some(Ring{ring:2568,used:COUNTER});let mut stats=crate::stats::Stats::default();stats.set_base(13,99);stats.set_current(13,99);let mut p=PlayerData::new(1,"Forging ring".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);for slot in 0..2{p.inventory.restore_slot(slot,Some(Item{id:440,count:1,vars:0})).unwrap();}p.inventory.restore_slot(27,Some(Item{id:2568,count:1,vars:0})).unwrap();if worn{p.equipment.restore_slot(12,Some(Item{id:2568,count:1,vars:0})).unwrap();}p.variables.set(COUNTER,used,false);w.queue_login(1,p).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.drain_events();(w,a,Arc::new(Request{product:2351,produced:1,consumed:vec![(440,1)],xp:12.5,animation:899,cycles:5,impurity:true,members:false,repeat_delay:None,required_level:15,required_tools:vec![]}))}
fn amount(w:&World,a:ActorId,id:i32)->i32{crate::smithing_make::total(&w.data(a).unwrap().inventory,&w.object_types,id)}
fn finish(w:&mut World,n:usize)->usize{let mut d=Draw(0);for _ in 0..n{w.tick_with_random(&mut d).unwrap();}d.0}
#[test]
fn forging_ring_guarantees_iron_for_free_and_member_players_and_stops_on_last_charge(){for member in[false,true]{for used in[0,1,138,139]{let(mut w,a,r)=prepared(used,true);w.set_membership(a,member).unwrap();w.start_smelting(a,r,5).unwrap();assert_eq!(finish(&mut w,20),0);let made=if used==139{1}else{2};assert_eq!(amount(&w,a,2351),made);assert_eq!(amount(&w,a,440),2-made);assert_eq!(w.data(a).unwrap().stats.fine_xp(13),125*made);let broken=used+made==140;assert_eq!(w.data(a).unwrap().variables.get(62400),if broken{0}else{used+made});assert_eq!(w.data(a).unwrap().equipment.get(12).is_none(),broken);assert!(!w.player(a).unwrap().queues.contains(900));let messages=w.drain_events().iter().filter(|e|matches!(e,WorldEvent::GameMessage{text,..}if text.contains("crumbles"))).count();assert_eq!(messages,usize::from(broken));}}}
#[test]
fn forging_ring_one_hundred_forty_successes_exhaust_one_ring_without_rng(){let(mut w,a,r)=prepared(0,true);w.data_mut(a).unwrap().inventory.restore_slot(1,None).unwrap();for i in 1..=140{w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:440,count:1,vars:0})).unwrap();for slot in 1..27{w.data_mut(a).unwrap().inventory.restore_slot(slot,None).unwrap();}w.start_smelting(a,r.clone(),1).unwrap();assert_eq!(finish(&mut w,6),0);assert_eq!(amount(&w,a,2351),1);assert_eq!(w.data(a).unwrap().stats.fine_xp(13),i*125);assert_eq!(w.data(a).unwrap().variables.get(62400),i%140);assert_eq!(w.data(a).unwrap().equipment.get(12).is_none(),i==140);}assert_eq!(amount(&w,a,2568),1);}
#[test]
fn forging_ring_live_swaps_use_character_counter_instead_of_refilling_each_item(){for late_on in[false,true]{let(mut w,a,r)=prepared(50,!late_on);w.start_smelting(a,r,1).unwrap();w.tick().unwrap();w.data_mut(a).unwrap().equipment.restore_slot(12,if late_on{Some(Item{id:2568,count:1,vars:0})}else{None}).unwrap();let draws=finish(&mut w,6);assert_eq!(draws,usize::from(!late_on));assert_eq!(amount(&w,a,2351),i32::from(late_on));assert_eq!(w.data(a).unwrap().variables.get(62400),if late_on{51}else{50});assert_eq!(amount(&w,a,2568),1);}let(mut w,a,r)=prepared(139,true);w.data_mut(a).unwrap().equipment.restore_slot(12,None).unwrap();let replacement=w.data(a).unwrap().inventory.get(27);w.data_mut(a).unwrap().equipment.restore_slot(12,replacement).unwrap();w.data_mut(a).unwrap().inventory.restore_slot(27,None).unwrap();w.start_smelting(a,r,5).unwrap();assert_eq!(finish(&mut w,20),0);assert_eq!(amount(&w,a,2351),1);assert_eq!(amount(&w,a,440),1);assert!(w.data(a).unwrap().equipment.get(12).is_none());}
#[test]
fn forging_ring_carried_wrongslot_malformed_or_other_item_cannot_guarantee_iron(){for case in 0..5{let(mut w,a,r)=prepared(10,false);match case{0=>{},1=>w.data_mut(a).unwrap().equipment.restore_slot(11,Some(Item{id:2568,count:1,vars:0})).unwrap(),2=>w.data_mut(a).unwrap().equipment.restore_slot(12,Some(Item{id:2568,count:2,vars:0})).unwrap(),3=>w.data_mut(a).unwrap().equipment.restore_slot(12,Some(Item{id:2568,count:1,vars:1})).unwrap(),_=>w.data_mut(a).unwrap().equipment.restore_slot(12,Some(Item{id:16359,count:1,vars:0})).unwrap()};let gear=w.data(a).unwrap().equipment.clone();w.start_smelting(a,r,1).unwrap();assert_eq!(finish(&mut w,6),1);assert_eq!(amount(&w,a,2351),0);assert_eq!(amount(&w,a,440),1);assert_eq!(w.data(a).unwrap().stats.fine_xp(13),0);assert_eq!(w.data(a).unwrap().variables.get(62400),10);assert_eq!(w.data(a).unwrap().equipment,gear);}}
#[test]
fn forging_ring_failed_requirements_xp_stock_state_or_life_cannot_spend_charge(){for case in 0..14{let(mut w,a,r)=prepared(139,true);w.start_smelting(a,r,2).unwrap();w.tick().unwrap();match case{0=>w.data_mut(a).unwrap().stats.set_current(13,14),1=>w.smithing.as_mut().unwrap().xp_rate=f64::INFINITY,2=>{for slot in 0..2{w.data_mut(a).unwrap().inventory.restore_slot(slot,None).unwrap();}},3=>w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:440,count:2,vars:0})).unwrap(),4=>w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:440,count:1,vars:9})).unwrap(),5=>{w.data_mut(a).unwrap().variables.set(COUNTER,-1,false);},6=>{w.data_mut(a).unwrap().variables.set(COUNTER,140,false);},7=>w.players.get_mut(a.slot as usize).unwrap().death_queued=true,8=>w.data_mut(a).unwrap().stats.set_current(3,0),9=>w.players.get_mut(a.slot as usize).unwrap().pending_logout=true,10=>{w.object_types.dummy.insert(2351);},11=>{w.object_types.stackable.insert(440);},12=>{w.data_mut(a).unwrap().variables.set(COUNTER,i32::MIN,false);},_=>{w.data_mut(a).unwrap().variables.set(COUNTER,i32::MAX,false);}}let before=w.data(a).unwrap().clone();finish(&mut w,12);if let Ok(d)=w.data(a){assert_eq!(d.inventory,before.inventory,"case{case}");assert_eq!(d.equipment,before.equipment);assert_eq!(d.stats,before.stats);assert_eq!(d.variables.get(62400),before.variables.get(62400));}assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SmithingProductMade{..}|WorldEvent::SkillAdvanced{..})));}}
#[test]
fn forging_ring_does_not_modify_generic_forging_or_changed_iron_recipe(){for change in 0..4{let(mut w,a,mut r)=prepared(9,true);if change==0{w.start_smithing(a,r,1).unwrap();}else{match change{1=>Arc::get_mut(&mut r).unwrap().xp=13.0,2=>Arc::get_mut(&mut r).unwrap().consumed=vec![(440,2)],_=>Arc::get_mut(&mut r).unwrap().required_level=14};w.start_smelting(a,r,1).unwrap();}assert_eq!(finish(&mut w,6),1);assert_eq!(amount(&w,a,2351),0);assert_eq!(w.data(a).unwrap().variables.get(62400),9);assert!(w.data(a).unwrap().equipment.get(12).is_some());}}
#[test]
fn forging_ring_player_wear_persists_across_variable_restore_and_ring_swap(){let(mut w,a,r)=prepared(138,true);w.start_smelting(a,r.clone(),1).unwrap();finish(&mut w,6);let saved=w.data(a).unwrap().variables.persistent(&[(62400,COUNTER)].into());assert_eq!(saved.get(&62400),Some(&139));let(mut next,b,r)=prepared(0,true);next.data_mut(b).unwrap().variables=crate::variables::Variables::restore(saved);next.start_smelting(b,r,5).unwrap();finish(&mut next,20);assert_eq!(amount(&next,b,2351),1);assert_eq!(amount(&next,b,440),1);assert!(next.data(b).unwrap().equipment.get(12).is_none());assert_eq!(next.data(b).unwrap().variables.get(62400),0);}
#[test]
fn forging_ring_check_reports_current_player_charges_and_held_break_resets_only_once(){let(mut w,a,_)=prepared(139,true);let before=w.data(a).unwrap().clone();w.submit(a,Action::ForgingRingItem{slot:12,item:2568,operation:2,worn:true}).unwrap();finish(&mut w,1);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::GameMessage{text,..}if text=="Your ring of forging has 1 charges remaining.")));assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().equipment,before.equipment);w.submit(a,Action::ForgingRingItem{slot:27,item:2568,operation:6,worn:false}).unwrap();finish(&mut w,1);assert_eq!(amount(&w,a,2568),0);assert_eq!(w.data(a).unwrap().variables.get(62400),0);assert!(w.data(a).unwrap().equipment.get(12).is_some());w.submit(a,Action::ForgingRingItem{slot:27,item:2568,operation:6,worn:false}).unwrap();finish(&mut w,1);assert_eq!(w.data(a).unwrap().stats,before.stats);assert_eq!(w.data(a).unwrap().variables.get(62400),0);}
#[test]
fn forging_ring_item_current_slot_life_modal_delay_and_operation_guards(){for case in 0..11{let(mut w,a,_)=prepared(42,true);match case{0=>w.players.get_mut(a.slot as usize).unwrap().saving=true,1=>w.players.get_mut(a.slot as usize).unwrap().pending_logout=true,2=>w.players.get_mut(a.slot as usize).unwrap().death_queued=true,3=>w.data_mut(a).unwrap().stats.set_current(3,0),4=>w.players.get_mut(a.slot as usize).unwrap().has_modal=true,5=>w.players.get_mut(a.slot as usize).unwrap().protection.delay(2),6=>w.data_mut(a).unwrap().inventory.restore_slot(27,None).unwrap(),7=>w.data_mut(a).unwrap().inventory.restore_slot(27,Some(Item{id:2568,count:2,vars:0})).unwrap(),8=>w.data_mut(a).unwrap().inventory.restore_slot(27,Some(Item{id:2568,count:1,vars:1})).unwrap(),_=>{}}let before=w.data(a).unwrap().clone();assert!(w.forging_ring_item(a,27,if case==9{2569}else{2568},if case==10{5}else{6},false).is_err(),"case{case}");assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().variables.get(62400),42);}}
#[test]
fn forging_ring_reward_keeps_existing_fractional_base_and_runtime_rates(){for(rate,global,xp)in[(100,1.0,125),(500,1.0,625),(250,1.0,312),(500,2.0,1250)]{let(mut w,a,r)=prepared(0,true);w.data_mut(a).unwrap().xp_rate_hundreds=rate;w.smithing.as_mut().unwrap().xp_rate=global;w.start_smelting(a,r,1).unwrap();finish(&mut w,6);assert_eq!(w.data(a).unwrap().stats.fine_xp(13),xp);assert_eq!(w.data(a).unwrap().variables.get(62400),1);}}
